class Solution {
    public long gridGame(int[][] grid){
        long top=0,bottom=0,answer=Long.MAX_VALUE;
        for(int value:grid[0])top+=value;
        for(int col=0;col<grid[0].length;col++){
            top-=grid[0][col];
            answer=Math.min(answer,Math.max(top,bottom));
            bottom+=grid[1][col];
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun gridGame(grid:Array<IntArray>):Long{
        var top=grid[0].sumOf{
            it.toLong()
        };
        var bottom=0L;
        var answer=Long.MAX_VALUE;
        for(col in grid[0].indices){
            top-=grid[0][col];
            answer=minOf(answer,maxOf(top,bottom));
            bottom+=grid[1][col]
        };
        return answer
    }
}

